function asObject(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function cleanString(value) {
  return String(value ?? '').trim();
}

const body = asObject($('Webhook').first().json.body);
const authorized = asObject($json);
const message = cleanString(body.message);
const normalized = message
  .toLowerCase()
  .replace(/[!?.]+$/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const conversationId = cleanString(authorized.conversation_id);
const businessId = cleanString(authorized.business_id);
const customerId = cleanString(authorized.customer_id) || null;
const customerName = cleanString(authorized.customer_name) || null;
const customerPhone = cleanString(authorized.customer_phone) || null;

if (!authorized.authorized) {
  throw new Error('chat session is not authorized');
}
if (!message) {
  throw new Error('message is required');
}
if (!conversationId || !businessId) {
  throw new Error('trusted conversation and business IDs are required');
}

const directResponses = [
  { pattern: /^(hi|hello|hey|salam|assalamualaikum|assalamu alaikum|good morning|good afternoon|good evening)$/, response: 'Hello! How can I help you today?' },
  { pattern: /^(how are you|how are you doing|how r u|how is it going|what is up|whats up)$/, response: "I'm doing well and ready to help with your appointment. What would you like to do?" },
  { pattern: /^(thanks|thank you|thx|jazakallah|jazak allah)$/, response: "You're welcome! Let me know if you need anything else." },
  { pattern: /^(bye|goodbye|see you|talk to you later)$/, response: 'Goodbye! Feel free to message again whenever you need help.' },
];

const isBookingOrAction = /(book|reschedul|cancel|availab|slot|appointment|confirm)/i.test(normalized);

const contextRoutes = [
  { intent: 'BUSINESS_HOURS', pattern: /(office hours|business hours|opening hours|working hours|hours|timings|timing|open time|closing time|close time|when are you open)/ },
  { intent: 'BUSINESS_PHONE', pattern: /(what is your phone|what is your number|contact phone|phone number\?|^phone$|^number$)/ },
  { intent: 'BUSINESS_EMAIL', pattern: /(what is your email|contact email|email address\?|^email$)/ },
  { intent: 'BUSINESS_ADDRESS', pattern: /(what is your address|where are you located|location|where is your clinic|directions|^address$)/ },
  { intent: 'BUSINESS_DURATION', pattern: /(how long are appointments|appointment duration|slot length)/ },
  { intent: 'BUSINESS_ABOUT', pattern: /(about the business|who are you)/ },
];

const direct = !isBookingOrAction ? directResponses.find((item) => item.pattern.test(normalized)) : null;
const context = !isBookingOrAction ? contextRoutes.find((item) => item.pattern.test(normalized)) : null;
const { customer_token: _customerToken, ...safeBody } = body;

return {
  json: {
    body: {
      ...safeBody,
      conversation_id: conversationId,
      business_id: businessId,
      customer_id: customerId,
      customer_name: customerName,
      customer_phone: customerPhone,
    },
    message,
    conversation_id: conversationId,
    business_id: businessId,
    customer_id: customerId,
    customer_name: customerName,
    customer_phone: customerPhone,
    route: direct
      ? { action: 'DIRECT_RESPONSE', response: direct.response }
      : context
        ? { action: 'DIRECT_CONTEXT_RESPONSE', intent: context.intent, query: message }
        : { action: 'GET_BUSINESS_CONTEXT', query: message },
  },
};

const DEFAULT_REPLY = 'Sorry, I could not process that request. Please try again.';
const AGENT_ERROR_REPLY = "I'm having trouble processing that with the AI assistant right now. Your saved details are unchanged; please try again in a moment.";

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function safeClone(value, fallback = {}) {
  if (value == null) return fallback;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return isPlainObject(parsed) ? parsed : fallback;
    } catch {
      return fallback;
    }
  }
  if (!isPlainObject(value)) return fallback;
  try {
    return JSON.parse(JSON.stringify(value));
  } catch {
    return fallback;
  }
}

function cleanString(value, fallback = '') {
  const text = String(value ?? '').trim();
  return text || fallback;
}

function stripCodeFence(value) {
  const fence = '\x60\x60\x60';
  let text = String(value ?? '').trim();
  if (text.toLowerCase().startsWith(fence + 'json')) text = text.slice(7).trim();
  if (text.startsWith(fence)) text = text.slice(3).trim();
  if (text.endsWith(fence)) text = text.slice(0, -3).trim();
  return text;
}

function parseAgentOutput(raw) {
  const fallback = { reply: DEFAULT_REPLY, workflow: 'NO_CHANGE', data: {} };
  if (raw == null || raw === '') return fallback;
  if (isPlainObject(raw)) return safeClone(raw, fallback);

  const text = stripCodeFence(raw);
  if (!text) return fallback;

  try {
    const parsed = JSON.parse(text);
    return isPlainObject(parsed) ? parsed : { ...fallback, reply: text };
  } catch {
    return { ...fallback, reply: text };
  }
}

function normalizeWorkflow(value) {
  const allowed = new Set([
    'BUSINESS_INFORMATION',
    'WAITING_FOR_DATE',
    'WAITING_FOR_SLOT',
    'WAITING_FOR_NAME',
    'WAITING_FOR_PHONE',
    'WAITING_FOR_CONFIRMATION',
    'BOOKED',
    'CANCELLED',
    'NO_CHANGE',
  ]);
  const normalized = cleanString(value, 'NO_CHANGE').toUpperCase();
  return allowed.has(normalized) ? normalized : 'NO_CHANGE';
}

function normalizeData(value) {
  const data = safeClone(value, {});
  const nested = safeClone(data.data, {});
  if (Object.keys(nested).length === 0) return data;
  const flattened = { ...data, ...nested };
  delete flattened.data;
  return flattened;
}

function findConversation(input) {
  const candidates = [input?.conversation, input, input?.data, input?.body, input?.json];
  for (const candidate of candidates) {
    if (
      isPlainObject(candidate) &&
      (
        candidate.state_json ||
        candidate.conversation_id ||
        candidate.id ||
        candidate.status ||
        candidate.current_state
      )
    ) {
      return safeClone(candidate, {});
    }
  }
  return {};
}

function titleCase(value) {
  return cleanString(value)
    .toLowerCase()
    .split('_')
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

function formatHours(hours) {
  if (!Array.isArray(hours) || hours.length === 0) {
    return 'Business hours are not available right now.';
  }
  const order = ['MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY', 'SUNDAY'];
  const grouped = new Map();
  for (const entry of hours) {
    const weekday = cleanString(entry.weekday).toUpperCase();
    if (!weekday || !entry.start_time || !entry.end_time) continue;
    if (!grouped.has(weekday)) grouped.set(weekday, []);
    grouped.get(weekday).push(String(entry.start_time) + '-' + String(entry.end_time));
  }
  const parts = [];
  for (const weekday of order) {
    const ranges = grouped.get(weekday);
    if (ranges?.length) parts.push(titleCase(weekday) + ' ' + ranges.join(', '));
  }
  return parts.length ? 'Our business hours are: ' + parts.join('; ') + '.' : 'Business hours are not available right now.';
}

function businessContextReply(intent, context) {
  const business = safeClone(context.business, {});
  const settings = safeClone(context.settings, {});
  switch (intent) {
    case 'BUSINESS_HOURS':
      return formatHours(context.business_hours);
    case 'BUSINESS_PHONE':
      return business.phone ? 'You can contact us at ' + business.phone + '.' : 'The business phone number is not available right now.';
    case 'BUSINESS_EMAIL':
      return business.email ? 'You can email us at ' + business.email + '.' : 'The business email is not available right now.';
    case 'BUSINESS_ADDRESS':
      return business.address ? 'Our address is ' + business.address + '.' : 'The business address is not available right now.';
    case 'BUSINESS_DURATION':
      return settings.appointment_duration_minutes ? 'Appointments are ' + settings.appointment_duration_minutes + ' minutes long.' : 'The appointment duration is not available right now.';
    case 'BUSINESS_ABOUT': {
      const name = cleanString(business.name, 'the business');
      return business.description ? name + ': ' + business.description : 'This is ' + name + '.';
    }
    default:
      return DEFAULT_REPLY;
  }
}

const classified = $('Classify Message').first().json;
const route = classified.route ?? { action: 'GET_BUSINESS_CONTEXT' };
const isSimpleDirect = route.action === 'DIRECT_RESPONSE';
const isContextDirect = route.action === 'DIRECT_CONTEXT_RESPONSE';
const previousSource = isSimpleDirect
  ? $('Get Conversation State Direct').first().json
  : $('Get Conversation State').first().json;
const previous = findConversation(previousSource);
const previousState = safeClone(previous.state_json, {});

const conversationId = cleanString(classified.conversation_id);
const businessId = cleanString(classified.business_id);
const channel = cleanString(classified.channel, 'WEB_CHAT');
const currentMessage = cleanString($('Webhook').first().json.body?.message);

if (!conversationId || !businessId) {
  throw new Error('conversation_id and business_id are required');
}

let reply = DEFAULT_REPLY;
let workflow = 'NO_CHANGE';
let data = {};

if (isSimpleDirect) {
  reply = cleanString(route.response, DEFAULT_REPLY);
} else if (isContextDirect) {
  reply = businessContextReply(route.intent, $json);
  workflow = 'BUSINESS_INFORMATION';
} else if ($json.error) {
  reply = AGENT_ERROR_REPLY;
} else {
  const rawOutput = $json.output ?? $json.text ?? $json.response ?? $json.result;
  const parsed = parseAgentOutput(rawOutput);
  reply = cleanString(
    parsed.reply ?? parsed.assistant_message ?? parsed.response,
    DEFAULT_REPLY,
  );
  workflow = normalizeWorkflow(parsed.workflow);
  data = normalizeData(parsed.data ?? parsed.booking);
}

for (const [key, trustedValue] of Object.entries({
  customer_id: classified.customer_id,
  customer_name: classified.customer_name,
  customer_phone: classified.customer_phone,
})) {
  if (trustedValue && Object.prototype.hasOwnProperty.call(data, key)) {
    data[key] = trustedValue;
  }
}

const state = {
  ...previousState,
  waiting_for: previousState.waiting_for ?? 'none',
  requested_date: previousState.requested_date ?? null,
  requested_time: previousState.requested_time ?? null,
  available_slots: Array.isArray(previousState.available_slots)
    ? previousState.available_slots
    : [],
  selected_slot: previousState.selected_slot ?? null,
  appointment_id: previousState.appointment_id ?? null,
  customer_id: classified.customer_id || data.customer_id || previousState.customer_id || null,
  customer_name: classified.customer_name || data.customer_name || previousState.customer_name || null,
  customer_phone: classified.customer_phone || data.customer_phone || previousState.customer_phone || null,
  customer_email: previousState.customer_email ?? null,
  whatsapp_number: previousState.whatsapp_number ?? null,
  notes: previousState.notes ?? null,
  start_datetime: previousState.start_datetime ?? null,
  end_datetime: previousState.end_datetime ?? null,
};

const trackedFields = [
  'requested_date',
  'selected_date',
  'date',
  'requested_time',
  'time',
  'selected_slot',
  'available_slots',
  'appointment_id',
  'customer_email',
  'whatsapp_number',
  'notes',
  'start_datetime',
  'end_datetime',
  'timezone',
  'status',
  'cancellation_reason',
];

for (const key of trackedFields) {
  if (Object.prototype.hasOwnProperty.call(data, key)) {
    state[key] = data[key];
  }
}

if (Object.prototype.hasOwnProperty.call(data, 'date')) {
  state.requested_date = data.date;
}
if (Object.prototype.hasOwnProperty.call(data, 'time')) {
  state.requested_time = data.time;
  state.selected_slot = data.time;
}
if (Object.prototype.hasOwnProperty.call(data, 'selected_date')) {
  state.requested_date = data.selected_date;
}
if (Object.prototype.hasOwnProperty.call(data, 'selected_slot')) {
  state.requested_time = data.selected_slot;
}

let currentState = cleanString(previous.current_state, 'START').toUpperCase();
let status = cleanString(previous.status, 'ACTIVE').toUpperCase();
if (!['ACTIVE', 'COMPLETED', 'EXPIRED'].includes(status)) {
  status = 'ACTIVE';
}

switch (workflow) {
  case 'BUSINESS_INFORMATION':
    if (state.waiting_for === 'none') {
      currentState = 'BUSINESS_INFORMATION';
    }
    status = 'ACTIVE';
    break;
  case 'WAITING_FOR_DATE':
    currentState = 'WAITING_FOR_DATE';
    status = 'ACTIVE';
    state.waiting_for = 'date';
    break;
  case 'WAITING_FOR_SLOT':
    currentState = 'WAITING_FOR_SLOT';
    status = 'ACTIVE';
    state.waiting_for = 'slot';
    break;
  case 'WAITING_FOR_NAME':
    currentState = 'WAITING_FOR_NAME';
    status = 'ACTIVE';
    state.waiting_for = 'name';
    break;
  case 'WAITING_FOR_PHONE':
    currentState = 'WAITING_FOR_PHONE';
    status = 'ACTIVE';
    state.waiting_for = 'phone';
    break;
  case 'WAITING_FOR_CONFIRMATION':
    currentState = 'WAITING_FOR_CONFIRMATION';
    status = 'ACTIVE';
    state.waiting_for = 'confirmation';
    break;
  case 'BOOKED':
    currentState = 'BOOKED';
    status = 'COMPLETED';
    state.waiting_for = 'none';
    break;
  case 'CANCELLED':
    currentState = 'CANCELLED';
    status = 'COMPLETED';
    state.waiting_for = 'none';
    break;
  case 'NO_CHANGE':
  default:
    break;
}

state.last_user_message = currentMessage;
state.last_assistant_message = reply;
state.last_updated_at = new Date().toISOString();

if (
  workflow === 'WAITING_FOR_SLOT' &&
  !Object.prototype.hasOwnProperty.call(data, 'date') &&
  state.requested_date
) {
  data.date = state.requested_date;
}
if (
  workflow === 'WAITING_FOR_SLOT' &&
  !Array.isArray(data.available_slots) &&
  Array.isArray(state.available_slots)
) {
  data.available_slots = state.available_slots;
}

const actionByWorkflow = {
  BUSINESS_INFORMATION: 'INFO',
  WAITING_FOR_DATE: 'RESPOND',
  WAITING_FOR_SLOT: 'SHOW_AVAILABLE_SLOTS',
  WAITING_FOR_NAME: 'RESPOND',
  WAITING_FOR_PHONE: 'RESPOND',
  WAITING_FOR_CONFIRMATION: 'BOOK_APPOINTMENT',
  BOOKED: 'BOOKING_CONFIRMED',
  CANCELLED: 'APPOINTMENT_CANCELLED',
  NO_CHANGE: 'RESPOND',
};

let action = actionByWorkflow[workflow] ?? 'RESPOND';
if (data.success === false) {
  action = workflow === 'BOOKED' ? 'BOOKING_FAILED' : 'ERROR';
}

const updatePayload = {
  business_id: businessId,
  current_state: currentState,
  status,
  state_json: state,
};

return {
  json: {
    action,
    reply,
    workflow,
    data,
    update_payload: updatePayload,
  },
};
